#include <iostream>

class Test {
public:
    explicit Test(int value = 0) : x(value) {}

    void print() const {
        // 1. Implicit access
        std::cout << "        x = " << x << "\n";
        // 2. Explicit access with arrow operator
        std::cout << "  this->x = " << this->x << "\n";
        // 3. Explicit access with dereference and dot operator
        std::cout << "(*this).x = " << (*this).x << "\n";
    }

private:
    int x;
};

int main() {
    Test testObject(12);
    testObject.print();
    return 0;
}

#include <iostream>
#include <iomanip>
#include <stdexcept>

class Time {
public:
    explicit Time(int hr = 0, int min = 0, int sec = 0) {
        setTime(hr, min, sec);
    }

    Time &setTime(int h, int m, int s) {
        setHour(h);
        setMinute(m);
        setSecond(s);
        return *this;
    }

    Time &setHour(int h) {
        if (h >= 0 && h < 24) {
            hour = static_cast<unsigned int>(h);
        } else {
            throw std::invalid_argument("hour must be 0-23");
        }
        return *this;
    }

    Time &setMinute(int m) {
        if (m >= 0 && m < 60) {
            minute = static_cast<unsigned int>(m);
        } else {
            throw std::invalid_argument("minute must be 0-59");
        }
        return *this;
    }

    Time &setSecond(int s) {
        if (s >= 0 && s < 60) {
            second = static_cast<unsigned int>(s);
        } else {
            throw std::invalid_argument("second must be 0-59");
        }
        return *this;
    }

    void printUniversal() const {
        std::cout << std::setfill('0')
                  << std::setw(2) << hour << ":"
                  << std::setw(2) << minute << ":"
                  << std::setw(2) << second << "\n";
    }

private:
    unsigned int hour{0};
    unsigned int minute{0};
    unsigned int second{0};
};

int main() {
    Time t;
    // Cascaded member-function calls
    t.setHour(18).setMinute(30).setSecond(22);
    std::cout << "Universal time: ";
    t.printUniversal();

    // Cascading with setTime
    t.setTime(20, 15, 45);
    std::cout << "New universal time: ";
    t.printUniversal();

    return 0;
}
